mapper.select:
SELECT target.* FROM crm_sales_target target WHERE 

    AND target.target_name LIKE CONCAT('%', #{query.targetName}, '%')
    AND target.target_no = #{query.targetNo}
    AND target.dimension_type = #{query.dimensionType}
    AND target.period_type = #{query.periodType}
    AND target.target_year = #{query.targetYear}
    AND target.target_period = #{query.targetPeriod}
    AND target.status = #{query.status}
    AND target.owner_id = #{query.ownerId}
    AND target.dept_id = #{query.deptId}
    AND target.calculation_basis = #{query.calculationBasis}
    AND target.currency = #{query.currency}

ORDER BY target.update_time DESC, target.sales_target_id DESC
